SELECT r.id, r.user_id, r.tool_name, r.arguments, r.metadata, r.status, r.conversation_id, r.turn_id, r.message_id, r.title, r.decision, r.expires_at, r.timed_out_at, r.approved_by_user_id, r.approved_at, r.executed_at, r.error_message, r.created_at, r.updated_at FROM (SELECT t.* FROM  (SELECT c.* , 0 AS should_delete FROM tool_approval_queue c)  t) r WHERE $criteria.CompositeIn("r", $WriterKeys)